const ids = ["G01","G02","G03","G04","G05","G06"];
const packets = {};
for (const id of ids) packets[id] = await tools.origin_packet({ case_id: id });

const result = [];
for (const id of ids) {
  const c = packets[id].cases[0];
  const ev = c.evidence;
  const src = new Map();
  for (const m of ev.material_index) src.set(m.id, m.source_id);
  const parents = new Map();
  for (const l of (ev.links || [])) {
    if (l.relation !== "derivation") continue;
    if (!parents.has(l.child)) parents.set(l.child, []);
    parents.get(l.child).push(l.parent);
  }
  const memo = new Map();
  const origins = (m, stack = new Set()) => {
    if (memo.has(m)) return memo.get(m);
    if (stack.has(m)) return [];
    const ps = parents.get(m);
    let out;
    if (!ps || ps.length === 0) {
      out = new Set([src.get(m)]);
    } else {
      out = new Set();
      const ns = new Set(stack); ns.add(m);
      for (const p of ps) for (const o of origins(p, ns)) out.add(o);
    }
    memo.set(m, out);
    return out;
  };
  const all = new Set();
  for (const m of ev.material_index) for (const o of origins(m.id)) if (o) all.add(o);
  const queries = c.query_ids.map(q => ({ material_id: q, origins: [...origins(q)].filter(Boolean).sort() }));
  result.push({ id: c.id, recorded_origin_count: all.size, independence: "unknown", queries });
}
return JSON.stringify({ cases: result });

