const ids = ["G01","G02","G03","G04","G05","G06"];
for (const id of ids) {
  const c = (await tools.origin_packet({ case_id: id })).cases[0];
  const ev = c.evidence;
  const src = new Map(ev.material_index.map(m => [m.id, m.source_id]));
  const allIds = new Set(src.keys());
  const parents = new Map();
  const missing = [];
  for (const l of ev.links) {
    if (l.relation !== "derivation") continue;
    if (!allIds.has(l.child) || !allIds.has(l.parent)) missing.push(l.child+">"+l.parent);
    if (!parents.has(l.child)) parents.set(l.child, []);
    parents.get(l.child).push(l.parent);
  }
  // fixed point iteration to handle cycles
  const acc = new Map([...allIds].map(m => [m, new Set()]));
  for (const m of allIds) if (!parents.get(m) || parents.get(m).length === 0) acc.get(m).add(src.get(m));
  let changed = true, iter = 0;
  while (changed && iter < 200) {
    changed = false; iter++;
    for (const m of allIds) {
      const ps = parents.get(m) || [];
      for (const p of ps) for (const o of acc.get(p)) if (!acc.get(m).has(o)) { acc.get(m).add(o); changed = true; }
    }
  }
  const all = new Set();
  for (const s of acc.values()) for (const o of s) all.add(o);
  console.log(id, "count:", all.size, "missingRefs:", missing.length, "iters:", iter, "selfloop:", [...parents].filter(([k,v])=>v.includes(k)).length);
  for (const q of c.query_ids) console.log("   ", q, JSON.stringify([...acc.get(q)].sort()));
}
